import re

ACCOUNT_CODE = re.compile(r'[A-Z]{2}-[0-9]{4}')

def valid_codes(rows: list[dict[str, object]]) -> list[str]:
    result: list[str] = []
    for row in rows:
        value = row.get('code')
        if not isinstance(value, str):
            raise ValueError('code must be a string')
        code = value.strip().upper()
        if ACCOUNT_CODE.fullmatch(code) is None:
            raise ValueError('code has invalid format')
        result.append(code)
    return result

