assert valid_codes([{'code': ' ab-1234 '}]) == ['AB-1234']
for bad in ([{'code': 'AB-1234-extra'}], [{'code': 1234}], [{}]):
    try:
        valid_codes(bad)
    except ValueError:
        pass
